import unittest

from support import run_cli

FILES = {
    "l.csv": "k,a\n1,x\n2,y\n3,z\n1,w\n",
    "r.csv": "k,a,b\n1,p,q\n1,r,s\n4,t,u\n",
    "names.csv": "id,name\n2,Ann\n1,Bob\n",
    "ages.csv": "id,age\n1,30\n2,25\n",
    "twice.csv": "k,a,a_right\n1,p,q\n",
    "empty.csv": "k,v\n",
    "case.csv": "k,v\nA,1\na,2\n 1,3\n01,4\n",
    "keys.csv": "k,w\na,x\n1,y\n",
    "nokey.csv": "id,v\n1,2\n",
    "bad.csv": "k,a\n1,x\n2\n",
}


class JoinTests(unittest.TestCase):
    def check(self, argv, rc, out, err=None):
        got = run_cli(*argv, files=FILES)
        self.assertEqual((got[0], got[1]), (rc, out), got[2])
        if err is None:
            self.assertEqual(got[2] != "", rc != 0)
        else:
            self.assertEqual(got[2], err)

    def test_inner_rows_in_left_then_right_order(self):
        argv = ("join", "l.csv", "r.csv", "k")
        text = "k  a  a_right  b\n1  x  p        q\n1  x  r        s\n1  w  p        q\n1  w  r        s\n"
        self.check(argv, 0, text)
        self.check(("--kind", "inner") + argv, 0, text)
        self.check(("--format", "csv") + argv, 0, "k,a,a_right,b\n1,x,p,q\n1,x,r,s\n1,w,p,q\n1,w,r,s\n")
        self.check(("--format=json",) + argv, 0,
                   '[{"k": "1", "a": "x", "a_right": "p", "b": "q"}, {"k": "1", "a": "x", "a_right": "r", "b": "s"}, '
                   '{"k": "1", "a": "w", "a_right": "p", "b": "q"}, {"k": "1", "a": "w", "a_right": "r", "b": "s"}]\n')

    def test_left_keeps_unmatched_rows_once(self):
        csv = "k,a,a_right,b\n1,x,p,q\n1,x,r,s\n2,y,,\n3,z,,\n1,w,p,q\n1,w,r,s\n"
        for argv in (("--kind", "left", "join", "l.csv", "r.csv", "k"), ("join", "l.csv", "r.csv", "k", "--kind=left"),
                     ("--kind=left", "join", "l.csv", "r.csv", "k"), ("join", "--kind", "left", "l.csv", "r.csv", "k")):
            self.check(("--format", "csv") + argv, 0, csv)
        self.check(("--format", "json", "--kind", "left", "join", "empty.csv", "names.csv", "k"), 1, "",
                   "tabula: names.csv: no column 'k' (columns: id, name)\n")

    def test_columns_and_order_of_left(self):
        self.check(("--format", "csv", "join", "names.csv", "ages.csv", "id"), 0, "id,name,age\n2,Ann,25\n1,Bob,30\n")
        self.check(("--format", "csv", "join", "ages.csv", "names.csv", "id"), 0, "id,age,name\n1,30,Bob\n2,25,Ann\n")

    def test_exact_text_match(self):
